KG42.register("clusters-a281c20b34487972cfc00a52",{"id":"05-double_auction::v142-d-CL002","paper":"05-double_auction","label":"Submitted electricity quantities as upper bounds and seller clearing priority","record":{"cluster_id":"v142-d-CL002","label":"Submitted electricity quantities as upper bounds and seller clearing priority","market_meaning":"Use the electricity quantities submitted by the two sides to constrain their respective allocated quantities, and apply a clearing order that prioritizes lower prices when sellers' asking prices differ. This cluster expresses local clearing constraints and does not claim to determine the complete trade allocation.","mechanism_ids":["v141-a-M01"],"market_types":["LEM"],"process_stages":["bidding","clearing"],"scope_disposition":"conditional","scope_explanation":"R001 and R002 serve only as shared interfaces for submission inputs. The different bidding behaviors in R002 retain their original conditions; seller priority for lower prices covers only comparisons between different asking prices.","assembly_status":"assembled","boundary_rationale":"There is an explicit constraint relationship between submitted and allocated quantities, and submitted asking prices have an explicit ordering purpose; these local constraints have independent market meaning, but neither price formation nor a complete allocation algorithm can be inferred from them.","chain_bindings":[{"chain_id":"v141-c-R003","ownership":"primary","role":"core","rationale":"Carries the allocation upper bounds for buyers and sellers and the procedural clearing priority for sellers."},{"chain_id":"v141-c-R001","ownership":"shared","role":"interface","rationale":"References only the buyer's submitted electricity quantity and sealed bid as clearing inputs; its primary assignment is to CL001."},{"chain_id":"v141-c-R002","ownership":"shared","role":"interface","rationale":"References only the seller's submission and the asking price generated by the selected behavior; its primary assignment is to CL001."}],"connections":[{"connection_id":"v142-d-CL002-L01","from_chain_id":"v141-c-R001","to_chain_id":"v141-c-R003","kind":"quantity_interface","from_refs":["v141-c-R001::x::v141-c-R001-x-BQ"],"to_refs":["v141-c-R003::theta::v141-c-R003.par.buyer_demand_quantity","v141-c-R003::phi::v141-c-R003-C001"],"evidence_ids":["v141-b-g01-ev-12","v141-b-g01-ev-13"],"rationale":"The demand quantity submitted by the same buyer becomes a fixed upper-bound input at the clearing stage, while the distinct roles of submission decision and clearing parameter are retained."},{"connection_id":"v142-d-CL002-L02","from_chain_id":"v141-c-R002","to_chain_id":"v141-c-R003","kind":"functional_coupling","from_refs":["v141-c-R002::phi::v141-c-R002-C004"],"to_refs":["v141-c-R003::theta::v141-c-R003.par.seller_supply_quantity","v141-c-R003::phi::v141-c-R003-C002"],"evidence_ids":["v141-b-g01-ev-12","v141-b-g01-ev-13"],"rationale":"The seller's submitted electricity quantity constrains the seller's allocation; because R002 does not declare the corresponding electricity-quantity object, only a functional interface is established here, without fabricating an object mapping for the same quantity."},{"connection_id":"v142-d-CL002-L03","from_chain_id":"v141-c-R002","to_chain_id":"v141-c-R003","kind":"functional_coupling","from_refs":["v141-c-R002::phi::v141-c-R002-C004"],"to_refs":["v141-c-R003::phi::v141-c-R003-C003"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-18b","v141-b-g02-E07"],"rationale":"The seller's asking price in the submission is used for comparisons that prioritize lower prices; the collective same-price assumption in the payoff game is not interpreted as a universal same-price clearing rule."}],"object_mappings":[{"mapping_id":"v142-d-CL002-O01","kind":"same_quantity","member_refs":["v141-c-R001::x::v141-c-R001-x-BQ","v141-c-R003::theta::v141-c-R003.par.buyer_demand_quantity"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g01-ev-12","v141-b-g01-ev-13"],"rationale":"For the same buyer in the same auction, the electricity demand quantity changes from a submission variable to a clearing input, with both local roles retained."},{"mapping_id":"v142-d-CL002-O02","kind":"same_node","member_refs":["v141-c-R001::V::bidding.demand","v141-c-R003::V::bidding.demand"],"canonical_ref":"v141-c-R001::V::bidding.demand","display_policy":"single_representative","evidence_ids":["v141-b-g01-ev-12","v141-b-g01-ev-13"],"rationale":"The same M01 demand-submission function is referenced repeatedly in the input chain and the upper-bound chain; only its display is consolidated."},{"mapping_id":"v142-d-CL002-O03","kind":"same_node","member_refs":["v141-c-R002::V::bidding.supply","v141-c-R003::V::bidding.supply"],"canonical_ref":"v141-c-R002::V::bidding.supply","display_policy":"single_representative","evidence_ids":["v141-b-g01-ev-12","v141-b-g01-ev-13"],"rationale":"The same M01 supply-submission function provides an input for the seller's allocation upper bound; this does not indicate that the quantity objects at the two stages have been merged."}],"gaps":[{"gap_id":"v142-d-CL002-G01","category":"math_incomplete","description":"The local upper bounds and procedural priority are already identifiable, but there is no closed algorithm for pairing, supply-demand conservation, equal-price handling, or partial execution; R003 also lacks an asking-price object usable for ordering. Allocated electricity quantities cannot be directly equated with transaction-level traded electricity quantities.","chain_ids":["v141-c-R003","v141-c-R002"],"object_refs":["v141-c-R003::phi::v141-c-R003-C003","v141-c-R003::x::v141-c-R003.var.buyer_cleared_quantity","v141-c-R003::x::v141-c-R003.var.seller_cleared_quantity","v141-c-R002::phi::v141-c-R002-C004"],"evidence_ids":["v141-b-g01-ev-12","v141-b-g01-ev-18b","v141-b-g02-E07"],"proposal_ids":["v141-b-g01-prop-01"],"required_work":"If this is extended into a complete clearing algorithm, B/C must complete the ordering, quantity allocation, and transaction-by-transaction correspondences; this cluster's assembled status is limited to the declared local constraints."},{"gap_id":"v142-d-CL002-G02","category":"unverified_source","description":"The B evidence for the electricity-quantity definitions and priority for lower prices has not yet been independently reviewed; local assembly does not certify its transcription or scientific correctness.","chain_ids":["v141-c-R001","v141-c-R002","v141-c-R003"],"object_refs":[],"evidence_ids":["v141-b-g01-ev-12","v141-b-g01-ev-13","v141-b-g01-ev-18b","v141-b-g02-E07"],"proposal_ids":[],"required_work":"Independently verify the definitions in Table 3 and the source text concerning natural ordering."}]},"rule_refs":["05-double_auction::v141-c-R003","05-double_auction::v141-c-R001","05-double_auction::v141-c-R002"],"unresolved_rule_refs":[],"node_ids":["COMP-60fa17e84f308f18","COMP-d90b7b5c0051250f","KG40-12aedc3eec573697","KG40-20f45ec4bdcbac06"]});
